import { test, expect } from '@playwright/test';

test.describe('ZIP Code Auto-Format', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('about:blank');
    await page.setContent(`
      <form>
        <label for="zipcode">ZIP Code</label>
        <input 
          id="zipcode" 
          type="text" 
          placeholder="Enter ZIP code"
          maxlength="10"
        />
        <div id="formatted-display"></div>
      </form>
      <script>
        const zipInput = document.getElementById('zipcode');
        const formattedDisplay = document.getElementById('formatted-display');

        function formatZipCode(value) {
          // Remove all non-digits
          const digits = value.replace(/\\D/g, '');

          // Format as XXXXX-XXXX for 9 digits, or XXXXX for 5 digits
          if (digits.length <= 5) {
            return digits;
          } else if (digits.length <= 9) {
            return digits.slice(0, 5) + '-' + digits.slice(5);
          } else {
            return digits.slice(0, 5) + '-' + digits.slice(5, 9);
          }
        }

        zipInput.addEventListener('input', (e) => {
          const formatted = formatZipCode(e.target.value);
          e.target.value = formatted;
          formattedDisplay.textContent = 'Formatted: ' + formatted;
        });
      </script>
    `);
  });

  test('should format 5-digit ZIP code without hyphen', async ({ page }) => {
    const zipInput = page.getByLabel('ZIP Code');

    await zipInput.fill('12345');

    await expect(zipInput).toHaveValue('12345');
    const formattedDisplay = page.locator('#formatted-display');
    await expect(formattedDisplay).toContainText('Formatted: 12345');
  });

  test('should format 9-digit ZIP code with hyphen after 5th digit', async ({ page }) => {
    const zipInput = page.getByLabel('ZIP Code');

    await zipInput.fill('123456789');

    await expect(zipInput).toHaveValue('12345-6789');
    const formattedDisplay = page.locator('#formatted-display');
    await expect(formattedDisplay).toContainText('Formatted: 12345-6789');
  });

  test('should remove non-numeric characters during formatting', async ({ page }) => {
    const zipInput = page.getByLabel('ZIP Code');

    await zipInput.fill('12-34a5-67b89');

    await expect(zipInput).toHaveValue('12345-6789');
    const formattedDisplay = page.locator('#formatted-display');
    await expect(formattedDisplay).toContainText('Formatted: 12345-6789');
  });

  test('should handle partial input and reformat on additional digits', async ({ page }) => {
    const zipInput = page.getByLabel('ZIP Code');

    // Type first 5 digits
    await zipInput.fill('12345');
    await expect(zipInput).toHaveValue('12345');

    // Add more digits
    await zipInput.fill('123456789');
    await expect(zipInput).toHaveValue('12345-6789');
  });

  test('should maintain format when user types slowly', async ({ page }) => {
    const zipInput = page.getByLabel('ZIP Code');

    await zipInput.type('1');
    await expect(zipInput).toHaveValue('1');

    await zipInput.type('2');
    await expect(zipInput).toHaveValue('12');

    await zipInput.type('3');
    await expect(zipInput).toHaveValue('123');

    await zipInput.type('4');
    await expect(zipInput).toHaveValue('1234');

    await zipInput.type('5');
    await expect(zipInput).toHaveValue('12345');

    await zipInput.type('6');
    await expect(zipInput).toHaveValue('12345-6');

    await zipInput.type('7');
    await expect(zipInput).toHaveValue('12345-67');

    await zipInput.type('8');
    await expect(zipInput).toHaveValue('12345-678');

    await zipInput.type('9');
    await expect(zipInput).toHaveValue('12345-6789');
  });

  test('should handle backspace and maintain format', async ({ page }) => {
    const zipInput = page.getByLabel('ZIP Code');

    await zipInput.fill('12345-6789');
    await expect(zipInput).toHaveValue('12345-6789');

    // Simulate backspace by removing last character
    await zipInput.fill('12345-678');
    await expect(zipInput).toHaveValue('12345-678');
  });

  test('should not exceed maximum length', async ({ page }) => {
    const zipInput = page.getByLabel('ZIP Code');

    // Try to input more than 9 digits
    await zipInput.fill('1234567890123');

    // Should be limited to 10 characters (5 digits + hyphen + 4 digits)
    const value = await zipInput.inputValue();
    expect(value.length).toBeLessThanOrEqual(10);
  });
});
